        END IF;
    ELSIF NEW.capability_code IN ('finance.adjustment_note.prepare','finance.adjustment_note.reversal.prepare','finance.bank_reconciliation.prepare','finance.customer_cheque_bounce.prepare','finance.customer_cheque_clearance.prepare','finance.customer_receipt.prepare','finance.expense_claim.prepare','finance.supplier_advance.prepare','finance.supplier_payment.prepare','inventory.adjustment.prepare','inventory.destruction.prepare','inventory.transfer.prepare','procurement.goods_receipt.prepare','procurement.purchase_order.prepare','procurement.purchase_return.prepare','procurement.purchase_return.reversal.prepare','procurement.supplier_invoice.prepare','sales.dispatch.prepare','sales.invoice.prepare','sales.order.prepare','sales.return.prepare','sales.return.reversal.prepare') THEN
        IF NEW.branch_id IS NULL
